export type UpsAreaMatch = { kind: "Extended Area" | "Remote Area"; perKg: number; minimum: number };

export function lookupUpsAreaSurcharge(countryCode: string, postalInput: string): UpsAreaMatch | null {
  const country = countryCode.toUpperCase();
  let postal = postalInput.trim().toUpperCase().replace(/[\\s-]/g, "");
  if (!postal) return null;
  if (country === "US" && /^\\d{9}$/.test(postal)) postal = postal.slice(0, 5);
  if (country === "GB") {
    const match = postal.match(/^([A-Z]{1,2}\\d[A-Z]?)\\d[A-Z]{2}$/);
    if (match) postal = match[1];
  }
  const numericPostal = /^\\d+$/.test(postal) ? Number(postal) : null;
  const countryRanges = UPS_AREA_RANGES[country];
  if (!countryRanges) return null;
  let found: 0 | 1 | null = null;
  for (let index = 0; index < countryRanges.length; index++) {
    for (const [low, high] of countryRanges[index]) {
      const numericRange = typeof low === "number" && typeof high === "number";
      const matches = numericRange && numericPostal !== null
        ? numericPostal >= low && numericPostal <= high
        : postal >= String(low) && postal <= String(high);
      if (matches && (found === null || index > found)) found = index as 0 | 1;
    }
  }
  if (found === 0) return { kind: "Extended Area", perKg: 0.62, minimum: 31.50 };
  if (found === 1) return { kind: "Remote Area", perKg: 0.66, minimum: 32.50 };
  return null;
}
